// CBET Academy acronym glossary. Every acronym used in the lessons, deep dives, and cheat sheet, plus those in questions.
// Rendered by the engine as hover links in tutorials and the cheat sheet (tip on hover, more on click) and as the
// cheat sheet's Acronyms section. Keys are matched as whole words, case-sensitive, plurals allowed. Original wording.
// Fields: full (what it stands for), tip (one sentence for the tooltip), more (the longer explanation; blank line = new paragraph).
window.FRA = window.FRA || {};
FRA.acronyms = {
  "802.11": { full: "IEEE 802.11", tip: "The family of Wi-Fi standards.", more: "802.11 defines wireless LANs. Its amendments are the generations you memorize: a, b, g, n (Wi-Fi 4), ac (Wi-Fi 5), ax (Wi-Fi 6 and 6E), and be (Wi-Fi 7), each with its bands, channel widths, and top speeds. Other amendments cover security (802.11i) and protected management frames (802.11w)." },
  "802.1X": { full: "IEEE 802.1X", tip: "Port-based network access control: a device must authenticate before the switch port or Wi-Fi passes traffic.", more: "With 802.1X the client (supplicant) presents credentials or a certificate through the switch or access point (authenticator) to a RADIUS server (authentication server) using EAP. Until it succeeds, the port only passes authentication traffic. It is the basis of WPA2 and WPA3 Enterprise and of wired NAC." },
  "AA": { full: "AA cell", tip: "A common single-cell battery size, about 1.5 V.", more: "Chemistry sets voltage per cell; a AA is one cell. Capacity is in amp-hours or watt-hours." },
  "AAMI": { full: "Association for the Advancement of Medical Instrumentation", tip: "The standards body for medical equipment and the sponsor of the CBET credential.", more: "AAMI publishes the EQ series standards for equipment management, the US adoption of IEC 60601, and guidance on sterilization and alarms. Its credentials institute runs the CBET, CRES, and CLES exams." },
  "ABC": { full: "Class A, B, and C fire extinguisher", tip: "A multipurpose extinguisher for ordinary combustibles, flammable liquids, and electrical fires.", more: "Class A is wood and paper, B is liquids, C is energized electrical, D is metals, K is cooking oils. An ABC dry chemical unit covers the first three." },
  "AC": { full: "Alternating current", tip: "Mains power that reverses direction, 60 Hz in the US and 50 Hz elsewhere.", more: "The 120 V wall voltage is an RMS value; the peak is about 170 V. Transformers only work on AC, and 60 Hz current mimics nerve pulses, which is why it causes muscle contraction and the let-go problem." },
  "ACGIH": { full: "American Conference of Governmental Industrial Hygienists", tip: "The organization that publishes threshold limit values.", more: "ACGIH TLVs are the most widely used exposure guidelines even though OSHA's PELs are the legal limits." },
  "ACHC": { full: "Accreditation Commission for Health Care", tip: "An accrediting body that absorbed the HFAP hospital program.", more: "ACHC, The Joint Commission, DNV, and CIHQ all hold CMS deeming authority for hospitals." },
  "ACI": { full: "AAMI Credentials Institute", tip: "The body within AAMI that administers the CBET and related certifications.", more: "ACI sets the exam content, eligibility, and recertification rules for CBET, CRES, CLES, and CHTM." },
  "ACK": { full: "Acknowledgment", tip: "The TCP flag or message confirming data arrived.", more: "TCP acknowledges received segments so the sender knows what to keep and what to resend. The ACK also finishes the three-way handshake. In the CBET course HL7 ACK messages confirm that an interface received a message." },
  "ADC": { full: "Analog-to-digital converter", tip: "Turns a continuous voltage into digital samples.", more: "The ADC's resolution (bits) and sampling rate set how faithfully a signal is captured; sampling must be at least twice the highest frequency (Nyquist)." },
  "ADT": { full: "Admit, discharge, transfer", tip: "The HL7 messages that tell every system who is in which bed.", more: "ADT feeds keep monitors, pumps, and labs matched to the right patient. A missing ADT feed is why a device cannot find a patient by bed." },
  "AE": { full: "Application entity", tip: "A DICOM node, identified by its AE title, IP address, and port.", more: "A modality must be configured with the PACS AE title, address, and port, and the PACS must know the modality's, or images will not transfer. A C-ECHO verifies the association." },
  "AED": { full: "Automated external defibrillator", tip: "A defibrillator that analyzes the rhythm and advises a shock only for VF or pulseless VT.", more: "AEDs are designed for lay rescuers: pads on, the device analyzes, and it charges only for shockable rhythms. Biomeds check pad expiration dates, battery, and self-test logs." },
  "AEM": { full: "Alternative equipment maintenance", tip: "A CMS-allowed program that adjusts maintenance from manufacturer recommendations based on risk and history.", more: "An AEM program lets a qualified person set different PM intervals when documented data supports it, except for imaging, lasers, and anything where the law or manufacturer forbids it." },
  "AF": { full: "Atrial fibrillation", tip: "An irregular rhythm with no P waves.", more: "In atrial fibrillation the atria quiver instead of contracting, giving an irregularly irregular pulse. Monitors detect it by the irregular R-R intervals and missing P waves." },
  "AHA": { full: "American Heart Association", tip: "The organization behind CPR guidelines and the US ECG electrode color code.", more: "The AHA color code is RA white, LA black, RL green, LL red, chest brown. Memory aid: white on the right, smoke over fire, and green for ground." },
  "ALARA": { full: "As low as reasonably achievable", tip: "The radiation safety principle: minimize dose with time, distance, and shielding.", more: "ALARA governs X-ray, CT, and nuclear medicine practice: shorter exposure, more distance, and lead shielding all reduce dose to staff and patients." },
  "ANSI": { full: "American National Standards Institute", tip: "The US body that accredits standards developers such as AAMI.", more: "ANSI/AAMI standards carry both names because ANSI approved AAMI's process." },
  "AP": { full: "Access point", tip: "The Wi-Fi radio that bridges wireless clients onto the wired network.", more: "One access point down affects one area; when every device everywhere drops, suspect the wireless controller or the authentication server. Medical telemetry and pumps roam between APs, so gaps in coverage drop moving devices." },
  "API": { full: "Application programming interface", tip: "The defined way one program talks to another, such as the web endpoints a cloud service exposes.", more: "APIs let software request data and actions from other software. Cloud consoles, SDN controllers, and mobile apps all work through APIs. Security concerns include stolen API keys, missing authentication, and rate limiting." },
  "APIPA": { full: "Automatic Private IP Addressing", tip: "The 169.254.x.x address a host gives itself when it cannot reach a DHCP server.", more: "When DHCP fails, Windows and other systems self-assign an address in 169.254.0.0/16 so hosts on the same segment can still talk. Seeing a 169.254 address is the classic sign that a client could not get a lease, which points at the DHCP server, the relay, or the link." },
  "ASME": { full: "American Society of Mechanical Engineers", tip: "The standards body for pressure vessels and boilers.", more: "Bulk oxygen tanks and sterilizer chambers are built to ASME codes." },
  "AV": { full: "Atrioventricular node", tip: "The relay between atria and ventricles that delays the impulse so the ventricles fill.", more: "The AV node introduces the PR interval delay, then passes the impulse to the bundle of His and Purkinje fibers. Blocks at the AV node lengthen the PR interval or drop beats. In Security+ AV means asset value or antivirus; read the context." },
  "AWG": { full: "American Wire Gauge", tip: "The wire size scale; smaller numbers are thicker wire with higher ampacity.", more: "AWG 10 wire carries more current than AWG 14. Ampacity tables set the maximum safe current for each gauge and insulation." },
  "BAA": { full: "Business associate agreement", tip: "The HIPAA contract a vendor signs before handling protected health information.", more: "Any vendor that touches PHI, including remote service providers, must sign a BAA and is directly liable under HITECH." },
  "BF": { full: "Body floating (applied part)", tip: "An applied part that touches the patient but not the heart, isolated from ground; stick-figure-in-a-box symbol.", more: "Type BF parts are electrically isolated (floating) from ground with tighter leakage limits than Type B. ECG electrodes and pulse oximeter probes are typically BF." },
  "BIOS": { full: "Basic Input/Output System", tip: "The original PC firmware: 16-bit, text setup, MBR disks up to 2 TB.", more: "BIOS initializes hardware, runs the power-on self-test, and hands off to the boot loader. It is limited to MBR disks and four primary partitions and has been replaced by UEFI, which many people still call the BIOS." },
  "BiPAP": { full: "Bilevel positive airway pressure", tip: "Two pressure levels, higher on inhalation and lower on exhalation, for non-invasive ventilation.", more: "BiPAP helps patients who tire on CPAP by lowering pressure during exhalation. It is delivered by mask and is a common step before intubation." },
  "BP": { full: "Blood pressure", tip: "The pressure in the arteries, systolic over diastolic, in mmHg.", more: "Normal adult blood pressure is around 120 over 80 mmHg. It is measured manually with a cuff and stethoscope, automatically by oscillometry (NIBP), or invasively with an arterial line (IBP)." },
  "C-ECHO": { full: "DICOM echo service", tip: "The DICOM ping that verifies two application entities can communicate.", more: "C-ECHO is the first test when a modality cannot send to PACS." },
  "CAP": { full: "College of American Pathologists", tip: "The organization that accredits clinical laboratories.", more: "CAP inspects labs and runs proficiency testing; its checklists cover analyzer maintenance and QC records." },
  "CBET": { full: "Certified Biomedical Equipment Technician", tip: "The AAMI credential for biomedical equipment technicians.", more: "The CBET exam, run by the AAMI Credentials Institute, covers anatomy and physiology, electricity and electronics, safety, medical equipment function, problem solving, and healthcare IT. It has 165 questions in three hours." },
  "CDA": { full: "Clinical Document Architecture", tip: "HL7's XML standard for clinical documents such as discharge summaries.", more: "CDA documents carry structured and narrative content and are the basis of continuity-of-care documents exchanged between providers." },
  "CDC": { full: "Centers for Disease Control and Prevention", tip: "The US public health agency that sets infection control guidance such as standard precautions.", more: "The CDC defined standard precautions in 1996, treating all body fluids as potentially infectious." },
  "CF": { full: "Cardiac floating (applied part)", tip: "An applied part that may connect directly to the heart, with the strictest leakage limits; heart-in-a-box symbol.", more: "Type CF parts allow only 10 microamps of patient leakage in normal conditions because current delivered to the heart can cause fibrillation at microamp levels. Cardiac catheters and pacing leads are CF. In the A+ course CF is the CompactFlash card; read the context." },
  "CFR": { full: "Code of Federal Regulations", tip: "The codified US federal rules; 29 CFR 1910 holds OSHA standards, 21 CFR the FDA's.", more: "The Hazard Communication Standard is 29 CFR 1910.1200; medical device reporting is in 21 CFR 803." },
  "CHIP": { full: "Children's Health Insurance Program", tip: "Federal and state health coverage for children, run by CMS.", more: "CHIP is one of the programs CMS administers alongside Medicare and Medicaid." },
  "CIA": { full: "Confidentiality, integrity, and availability", tip: "The three goals of security: keep data secret, keep it correct, keep it reachable.", more: "Confidentiality means only authorized people can read data (encryption, access control). Integrity means it has not been altered (hashes, signatures). Availability means systems are up when needed (redundancy, backups). Every attack and every control on the exam maps to one or more of the three; ransomware, for instance, attacks availability." },
  "CIHQ": { full: "Center for Improvement in Healthcare Quality", tip: "A newer CMS-approved hospital accreditor.", more: "CIHQ is among the organizations with deeming authority alongside The Joint Commission, DNV, and ACHC." },
  "CMMS": { full: "Computerized maintenance management system", tip: "The database that tracks equipment inventory, work orders, and preventive maintenance.", more: "The CMMS holds every device's record: location, PM schedule, history, and risk score. Accreditors ask for its reports to prove the maintenance program works." },
  "CMOS": { full: "Complementary metal-oxide semiconductor", tip: "The small battery-backed memory that keeps firmware settings and the clock.", more: "The CMOS chip stores BIOS or UEFI settings and time, kept alive by a CR2032 coin cell. A dead cell resets the clock and settings at every boot. Clearing CMOS with a jumper resets a forgotten firmware password." },
  "CMRR": { full: "Common-mode rejection ratio", tip: "How well an amplifier cancels signals present on both inputs, such as 60 Hz interference.", more: "ECG and EEG front ends need high CMRR (over 100 dB) to pull a millivolt or microvolt signal out of volts of mains interference. Unbalanced electrode impedance degrades it." },
  "CMS": { full: "Centers for Medicare and Medicaid Services", tip: "The federal agency whose Conditions of Participation hospitals must meet to be paid.", more: "CMS runs Medicare, Medicaid, and CHIP, regulates human lab testing, and sets the rules that accreditors survey against, including equipment maintenance and AEM." },
  "CO": { full: "Carbon monoxide", tip: "A toxic gas that binds hemoglobin and makes pulse oximeters read falsely high.", more: "Carboxyhemoglobin absorbs light like oxyhemoglobin, so a standard pulse oximeter cannot see CO poisoning; a co-oximeter is needed." },
  "CO2": { full: "Carbon dioxide", tip: "The gas exhaled as the waste product of metabolism; measured by capnography, and the lasing medium of CO2 surgical lasers.", more: "Blowing off CO2 raises blood pH; retaining it lowers pH. Capnography measures it in exhaled breath. CO2 lasers cut skin and soft tissue with little penetration. CO2 fire extinguishers are safe on electrical fires." },
  "COPD": { full: "Chronic obstructive pulmonary disease", tip: "Long-term airway obstruction, usually from smoking, with a low FEV1/FVC ratio.", more: "COPD patients retain CO2 and may depend on low oxygen levels to drive breathing, which affects how oxygen is delivered." },
  "CPAP": { full: "Continuous positive airway pressure", tip: "A constant pressure applied to the airway of a spontaneously breathing patient.", more: "CPAP holds the airway open for sleep apnea and supports oxygenation in respiratory distress. It provides no breaths; the patient does all the work." },
  "CPR": { full: "Cardiopulmonary resuscitation", tip: "Chest compressions and breaths to keep blood moving during cardiac arrest.", more: "Capnography during CPR confirms that compressions are producing circulation, because exhaled CO2 rises when blood reaches the lungs." },
  "CPU": { full: "Central processing unit", tip: "The processor that executes instructions.", more: "The CPU's cores, threads, clock speed, and cache set a computer's performance. Sudden CPU spikes are a security indicator for crypto mining or malware. In the A+ course you match its socket (LGA, PGA, AM4, AM5) to the motherboard and keep it cool." },
  "CT": { full: "Computed tomography", tip: "Cross-sectional X-ray imaging from a rotating tube and detector array.", more: "CT reconstructs slices from many X-ray projections. It delivers a higher dose than plain radiography and uses power injectors for contrast." },
  "DAC": { full: "Digital-to-analog converter", tip: "Turns digital values back into a voltage to drive displays, speakers, or outputs.", more: "A DAC does the reverse of an ADC. In Network+ the letters mean direct attach cable and in Security+ discretionary access control; read the context." },
  "dB": { full: "Decibel", tip: "A logarithmic ratio unit for signal levels, gain, and sound.", more: "Every 3 dB doubles power and every 10 dB multiplies it by ten. Audiometers report hearing thresholds in dB HL; amplifiers quote CMRR in dB; Wi-Fi signal is in dBm." },
  "DBP": { full: "Diastolic blood pressure", tip: "The arterial pressure between beats, while the heart fills.", more: "Diastolic pressure is the last Korotkoff sound and the bottom number. It lasts longer than systole, which is why mean arterial pressure sits closer to it." },
  "DC": { full: "Direct current", tip: "Current in one direction: batteries and power supply outputs.", more: "Capacitors block DC and pass AC, which is how they smooth ripple in power supplies and couple signals in amplifiers." },
  "DHCP": { full: "Dynamic Host Configuration Protocol", tip: "Hands out IP addresses, masks, gateways, and DNS servers automatically (UDP 67 and 68).", more: "A DHCP server leases addresses to clients through the DORA exchange: Discover, Offer, Request, Acknowledge. The lease also carries the subnet mask, default gateway, DNS servers, and options such as a TFTP server. Because Discover is a broadcast, a router needs a relay (IP helper) to reach a server on another subnet. Reservations tie a fixed address to a MAC; scopes and exclusions define the pool." },
  "DICOM": { full: "Digital Imaging and Communications in Medicine", tip: "The standard for medical image files and their network exchange, by convention on port 104.", more: "DICOM defines both the file (tagged fields such as patient name, study date, modality, pixel data) and the network services (store, query, retrieve, echo). Each device is an application entity with an AE title, IP address, and port." },
  "DISS": { full: "Diameter Index Safety System", tip: "Gas-specific threaded fittings that make it impossible to connect the wrong gas hose.", more: "DISS fittings on hoses, like pin-index on small cylinders, prevent cross-connection of oxygen, air, nitrous oxide, and vacuum." },
  "dL": { full: "Deciliter", tip: "One tenth of a liter; lab values such as glucose in mg per dL.", more: "Normal fasting glucose is roughly 70 to 100 mg/dL; hypoglycemia is dangerous within minutes." },
  "DMCA": { full: "Digital Millennium Copyright Act", tip: "The 1998 copyright law that bans circumventing digital protections.", more: "DMCA matters for service software: bypassing manufacturer access controls can be a violation, with exemptions for repair of some devices." },
  "DMM": { full: "Digital multimeter", tip: "The handheld meter for voltage, current, resistance, and continuity.", more: "A DMM (or DVM) is the first tool for power supply and cable checks. True-RMS models are needed for non-sine waveforms." },
  "DNA": { full: "Deoxyribonucleic acid", tip: "The genetic material; sterilization kills microbes by destroying it.", more: "Autoclaves and radiation sterilize by breaking microbial DNA." },
  "DNS": { full: "Domain Name System", tip: "Translates names such as www.example.com into IP addresses (UDP 53, TCP 53 for zone transfers).", more: "DNS is a distributed database of names. A resolver asks recursive servers, which walk from the root to the top-level domain to the authoritative server for the zone. Record types include A (IPv4), AAAA (IPv6), CNAME (alias), MX (mail), PTR (reverse), TXT (text such as SPF), SRV (service location), NS, and SOA. If a site works by IP address but not by name, DNS is the problem." },
  "DNV": { full: "DNV Healthcare", tip: "An accrediting organization that surveys hospitals annually under its NIAHO program.", more: "DNV integrates CMS Conditions of Participation with ISO 9001 quality management." },
  "DOT": { full: "Department of Transportation", tip: "The US agency whose rules govern compressed gas cylinders.", more: "Medical gas cylinders must meet DOT, Transport Canada, or ASME specifications and be tested and labeled accordingly." },
  "DVM": { full: "Digital voltmeter", tip: "A meter for voltage; in practice the same instrument as a DMM.", more: "DVM and DMM are used interchangeably for the bench multimeter." },
  "ECG": { full: "Electrocardiogram", tip: "The recording of the heart's electrical activity: P wave, QRS complex, T wave.", more: "An ECG monitor amplifies millivolt signals from skin electrodes using a high common-mode rejection front end. The P wave is atrial depolarization, the QRS is ventricular depolarization, and the T wave is ventricular repolarization. Twelve leads come from ten electrodes. Noise usually traces to electrodes, lead wires, or 60 Hz interference." },
  "ECRI": { full: "ECRI Institute", tip: "The independent organization that tests devices and publishes hazard alerts and the annual top-ten hazards list.", more: "ECRI alerts and recall notices are a primary source for equipment safety information." },
  "EDI": { full: "Electronic data interchange", tip: "Standardized electronic exchange of business documents such as claims and payments.", more: "HIPAA's administrative simplification requires EDI standards for claims, reducing paperwork and cost." },
  "EEG": { full: "Electroencephalogram", tip: "The recording of the brain's electrical activity from scalp electrodes, in microvolts.", more: "EEG signals are far smaller than ECG signals, so electrode impedance, shielding, and amplifier noise matter even more. It is used for seizure diagnosis and sleep studies." },
  "EHR": { full: "Electronic health record", tip: "The patient's longitudinal digital record, shared across providers.", more: "EHR emphasizes exchange between organizations; EMR is one organization's record. In practice the terms overlap." },
  "EM": { full: "Electromagnetic", tip: "Electric and magnetic fields; EM interference disrupts monitors and telemetry.", more: "Noise from motors, ESUs, and radios enters through cables and electrodes. Shielding, filtering, and distance reduce it." },
  "EMG": { full: "Electromyogram", tip: "The recording of muscle electrical activity.", more: "EMG measures muscle signals with surface or needle electrodes and is used with nerve conduction studies. Its interference is also what corrupts ECG traces when a patient shivers." },
  "EMI": { full: "Electromagnetic interference", tip: "Noise from motors, power lines, fluorescent lights, and radios that corrupts signals on copper cable.", more: "EMI induces unwanted voltage on cables and shows up as errors, CRC failures, or dropped links, especially on long unshielded runs near electrical equipment. Shielded cable, better routing, or fiber (which is immune) are the fixes. In the CBET course it also explains noisy ECG and EEG traces." },
  "EMR": { full: "Electronic medical record", tip: "The hospital's clinical record system: orders, notes, results, medications.", more: "Monitors, pumps, and labs integrate with the EMR through HL7 interfaces. EMR and EHR are used interchangeably on the exam." },
  "EQ": { full: "AAMI EQ series", tip: "AAMI's equipment management standards: EQ56, EQ89, EQ93, EQ103.", more: "The EQ standards define how a medical equipment management program is built, how maintenance is scheduled, the vocabulary used, and how alternative maintenance is justified." },
  "EQ103": { full: "ANSI/AAMI EQ103", tip: "Guidance for alternative equipment maintenance programs.", more: "EQ103 explains how to justify and document AEM intervals with data." },
  "EQ56": { full: "ANSI/AAMI EQ56", tip: "The recommended practice for a medical equipment management program.", more: "EQ56 describes inventory, risk assessment, maintenance strategy, records, and quality measures for the program as a whole." },
  "EQ89": { full: "ANSI/AAMI EQ89", tip: "Guidance for scheduled maintenance and performance verification.", more: "EQ89 covers what to check, how often, and how to verify performance during PM." },
  "EQ93": { full: "ANSI/AAMI EQ93", tip: "The vocabulary of medical equipment management.", more: "EQ93 standardizes terms so records and reports mean the same thing everywhere." },
  "ESD": { full: "Electrostatic discharge", tip: "Static electricity that can destroy chips; prevented with a wrist strap, mat, and antistatic bags.", more: "A static shock you cannot feel can still kill a component. Wear a strap connected to ground, work on an antistatic mat, and keep parts in their bags. Never wear a strap inside a power supply or CRT, which hold lethal voltages." },
  "ESU": { full: "Electrosurgical unit", tip: "The generator that cuts and coagulates tissue with high-frequency current above about 100 kHz.", more: "An ESU uses radio-frequency current, too fast for nerves and muscles to respond, so it heats tissue without shocking the patient. Monopolar mode needs a return electrode pad and its contact-quality monitor; bipolar mode passes current only between the forceps tips. Analyzers check output power, crest factor, and RF leakage." },
  "EtCO2": { full: "End-tidal carbon dioxide", tip: "The CO2 concentration at the end of exhalation, normally 35 to 45 mmHg, measured by capnography.", more: "EtCO2 tracks ventilation breath by breath. It confirms endotracheal tube placement, shows whether CPR is effective, and warns of a disconnected ventilator circuit before oxygen saturation falls. Mainstream sensors sit in the airway; sidestream sensors draw a sample through tubing." },
  "ETO": { full: "Ethylene oxide", tip: "A toxic gas used to sterilize heat-sensitive devices.", more: "ETO sterilizers require long aeration and strict ventilation because the gas is carcinogenic. Peroxide plasma is the common alternative." },
  "FDA": { full: "Food and Drug Administration", tip: "The US regulator of medical devices; classes I to III, recalls, and medical device reporting.", more: "The FDA clears or approves devices, requires manufacturers and hospitals to report deaths and serious injuries, and manages recalls. The Safe Medical Devices Act created the hospital reporting duty." },
  "FDG": { full: "Fluorodeoxyglucose", tip: "The glucose-like radioactive tracer used in PET scans.", more: "Fluorine-18 FDG concentrates in metabolically active tissue such as tumors, and its positrons produce the signal PET detects." },
  "FEV1": { full: "Forced expiratory volume in one second", tip: "The volume exhaled in the first second of a forced breath out.", more: "FEV1 divided by FVC is the key spirometry ratio; a low ratio indicates obstruction such as asthma or COPD." },
  "FHIR": { full: "Fast Healthcare Interoperability Resources", tip: "HL7's web-style standard using REST APIs and JSON resources.", more: "FHIR exposes patients, observations, and orders as web resources, making it easier for apps and devices to exchange data than the older pipe-delimited messages." },
  "FHR": { full: "Fetal heart rate", tip: "The baby's heart rate, measured by ultrasound Doppler on a fetal monitor.", more: "A Doppler transducer strapped to the abdomen detects fetal heart motion. Inconsistent readings usually mean transducer placement or gel." },
  "FiO2": { full: "Fraction of inspired oxygen", tip: "The oxygen concentration being delivered, from 0.21 (room air) to 1.0.", more: "Ventilators and blenders set FiO2. Oxygen analyzers are calibrated at 21 and 100 percent to verify it." },
  "FSH": { full: "Follicle-stimulating hormone", tip: "The pituitary hormone that drives sperm production and egg development.", more: "FSH and LH are the reproductive hormones covered in the anatomy and physiology domain." },
  "FVC": { full: "Forced vital capacity", tip: "The total volume a patient can exhale forcefully after a full breath in.", more: "Spirometry reports FVC and FEV1. A reduced FVC suggests restrictive disease." },
  "Gbps": { full: "Gigabits per second", tip: "Billions of bits per second; gigabit Ethernet is 1 Gbps.", more: "Gigabit Ethernet runs at 1 Gbps over Cat 5e, 10 Gbps over Cat 6A or fiber, and 40 to 400 Gbps in data centers. Divide by 8 for bytes." },
  "GFCI": { full: "Ground-fault circuit interrupter", tip: "A receptacle or breaker that trips when current leaking to ground exceeds about 5 mA.", more: "A GFCI compares current in the hot and neutral wires and opens the circuit if they differ, protecting people in wet locations. It does not protect against microshock, which needs isolation and low leakage." },
  "GHS": { full: "Globally Harmonized System", tip: "The international standard for chemical hazard labels and safety data sheets.", more: "GHS defines the pictograms (flame, skull, exclamation mark, health hazard) and the sixteen SDS sections that OSHA's hazard communication standard adopted." },
  "GHz": { full: "Gigahertz", tip: "Billions of cycles per second; CPU clock speed and Wi-Fi band frequency.", more: "A 3.5 GHz CPU ticks 3.5 billion times a second. Wi-Fi uses the 2.4, 5, and 6 GHz bands, where higher frequency means more bandwidth but shorter range and worse wall penetration." },
  "GI": { full: "Gastrointestinal", tip: "The digestive tract.", more: "GI bleeding is one of the conditions that alters lab values and device readings, and endoscopes are the GI department's main equipment." },
  "H2O": { full: "Water", tip: "The pressure unit centimeters of water (cmH2O) for airway and ventilator pressures.", more: "Ventilator pressures such as PEEP are set in cmH2O. 1 mmHg equals 1.36 cmH2O, so 13.6 cmH2O is 10 mmHg." },
  "HDD": { full: "Hard disk drive", tip: "Spinning magnetic storage: cheap per terabyte, slower, and fragile.", more: "HDDs spin platters at 5400 or 7200 rpm and read them with a moving head, so they are slow to seek and vulnerable to shock. Clicking, slow response, and S.M.A.R.T. warnings mean replace it and restore from backup." },
  "HFAP": { full: "Healthcare Facilities Accreditation Program", tip: "The former osteopathic hospital accreditation program, now part of ACHC.", more: "HFAP was one of the older deemed-status accreditors before its transfer to ACHC." },
  "HHS": { full: "Department of Health and Human Services", tip: "The US department that enforces HIPAA through its Office for Civil Rights.", more: "Breaches are reported to HHS, which posts large ones publicly and can fine organizations." },
  "HIPAA": { full: "Health Insurance Portability and Accountability Act", tip: "The US law protecting health information; Title II holds the privacy and security rules.", more: "HIPAA's titles cover insurance portability (I), administrative simplification with privacy, security, and EDI (II), tax rules (III), group plans (IV), and revenue (V). The Security Rule requires administrative, physical, and technical safeguards." },
  "HITECH": { full: "Health Information Technology for Economic and Clinical Health Act", tip: "The 2009 law that funded EHR adoption and strengthened HIPAA enforcement and breach notification.", more: "HITECH created meaningful-use incentives, made business associates directly liable, raised penalties, and required breach notification to individuals and HHS." },
  "HITRUST": { full: "Health Information Trust Alliance", tip: "A certifiable security framework that combines HIPAA, NIST, and other requirements for healthcare.", more: "HITRUST certification demonstrates that an organization or vendor meets a unified set of controls, which hospitals often require of vendors handling PHI." },
  "HIV": { full: "Human immunodeficiency virus", tip: "A bloodborne virus; one of the pathogens the OSHA bloodborne pathogen standard addresses.", more: "Hepatitis B, hepatitis C, and HIV spread through blood, which is why sharps handling and PPE rules exist." },
  "HL": { full: "Hearing level", tip: "The decibel scale audiometers use, referenced to normal hearing thresholds.", more: "Audiometers report thresholds in dB HL, where 0 dB HL is the average normal threshold at each frequency. Calibration checks the output at each frequency and level." },
  "HL7": { full: "Health Level Seven", tip: "The messaging standard that connects clinical systems: version 2 pipes, version 3 XML, FHIR web APIs.", more: "HL7 version 2 messages are pipe-delimited segments such as MSH (header), PID (patient), OBR (order), and OBX (observation). ADT messages carry admissions and transfers, ORM orders, ORU results, and ACK acknowledgments. An interface engine maps codes and units between systems." },
  "HR": { full: "Heart rate", tip: "Beats per minute, derived from the ECG or pulse.", more: "Monitors compute heart rate from QRS detection; pulse oximeters from the pulse waveform. An interface engine maps the monitor's HR field to the EMR's code for heart rate." },
  "HTTP": { full: "Hypertext Transfer Protocol", tip: "Web traffic in the clear on TCP 80.", more: "HTTP carries web pages and API calls without encryption, so anything sent can be read on the path. HTTPS on 443 is the secure form, and modern sites redirect to it." },
  "HTTPS": { full: "Hypertext Transfer Protocol Secure", tip: "HTTP inside TLS on TCP 443.", more: "HTTPS encrypts web traffic and lets the browser verify the server's certificate. The padlock means the connection to that server is private, not that the site is honest. DoH also rides on 443." },
  "HV": { full: "High voltage", tip: "The kilovolt sections of X-ray generators, defibrillators, and ESUs.", more: "A blown HV fuse means no output. Discharge capacitors before servicing high-voltage sections." },
  "HVAC": { full: "Heating, ventilation, and air conditioning", tip: "The building's climate systems, which keep server rooms cool and are themselves networked controls.", more: "Equipment fails when HVAC does. Building automation puts HVAC on the network, where it must be segmented like any other IoT." },
  "Hz": { full: "Hertz", tip: "Cycles per second; display refresh rate, AC mains frequency, and signal frequency.", more: "A 60 Hz monitor redraws 60 times a second; gaming panels run 120 to 240 Hz. Mains power is 60 Hz in North America and 50 Hz in much of the world, which matters for equipment and for why a 60 Hz shock makes muscles contract." },
  "IaaS": { full: "Infrastructure as a service", tip: "The provider supplies virtual machines, storage, and networks; you manage the operating system and up.", more: "IaaS rents raw computing. You install and patch the OS and applications while the provider runs the hardware. The exam cue is you manage the OS, they manage the hardware." },
  "IABP": { full: "Intra-aortic balloon pump", tip: "A balloon in the aorta that inflates in diastole and deflates in systole to support the heart.", more: "The IABP is timed to the ECG or arterial waveform. Helium fills the balloon because it moves fast and dissolves harmlessly if it leaks." },
  "IARC": { full: "International Agency for Research on Cancer", tip: "The WHO body that classifies carcinogens.", more: "Carcinogen listings come from IARC, the National Toxicology Program, and OSHA." },
  "IBP": { full: "Invasive blood pressure", tip: "Pressure measured directly through an arterial line and a transducer.", more: "IBP uses a fluid-filled catheter, a pressurized flush bag at about 300 mmHg, and a strain-gauge transducer that must be zeroed to atmosphere and leveled at the phlebostatic axis. Overdamped traces round off; underdamped traces overshoot; the fast-flush test tells which." },
  "IC": { full: "Integrated circuit", tip: "A chip: many transistors on one piece of silicon.", more: "ICs include op-amps, microcontrollers, and memory. Active components such as transistors and ICs need a power source and provide gain; passive components do not." },
  "ICMP": { full: "Internet Control Message Protocol", tip: "The protocol behind ping and traceroute.", more: "Ping sends ICMP echo requests; a reply proves the network path works even when an application does not." },
  "ICU": { full: "Intensive care unit", tip: "The critical care area with the highest density of monitors, ventilators, and pumps.", more: "ICU rooms have bedside monitors on a central station network; a problem affecting several rooms usually points to the network." },
  "ID": { full: "Identification", tip: "A patient identifier or a device identifier.", more: "DICOM headers and HL7 messages carry patient ID fields; matching them correctly is what keeps results with the right patient." },
  "IEC": { full: "International Electrotechnical Commission", tip: "The international standards body; IEC 60601-1 is the medical electrical equipment safety standard.", more: "IEC 60601-1 defines applied-part types (B, BF, CF), leakage current limits, and insulation classes; IEC 80001 covers risk management of medical devices on IT networks. Its color code for cords is brown live, blue neutral, green-yellow ground." },
  "IEEE": { full: "Institute of Electrical and Electronics Engineers", tip: "The engineering body behind Ethernet (802.3), Wi-Fi (802.11), and many device standards.", more: "IEEE numbers appear throughout networking; in healthcare, IEEE 11073 covers device communication." },
  "IP": { full: "Internet Protocol", tip: "The Layer 3 protocol that addresses and routes packets between networks.", more: "IP gives every host a logical address and lets routers forward packets from network to network using that address. Version 4 uses 32-bit addresses written as four numbers; version 6 uses 128-bit addresses written in hex. IP itself is best effort: it does not guarantee delivery, which is why TCP exists above it." },
  "IPv4": { full: "Internet Protocol version 4", tip: "32-bit addresses written as four decimal octets, such as 192.168.1.10.", more: "IPv4 addresses are 32 bits split into four octets. A subnet mask or CIDR prefix says which bits name the network and which name the host. Because there are only about four billion addresses, private ranges plus NAT are used inside organizations. Most subnetting math on the exam is IPv4." },
  "IPv6": { full: "Internet Protocol version 6", tip: "128-bit addresses in eight hex groups; no broadcast, built-in autoconfiguration.", more: "IPv6 uses 128-bit addresses written as hex groups separated by colons, with rules for shortening runs of zeros. There is no broadcast; multicast and neighbor discovery take its place. Hosts can build their own address from a router advertisement (SLAAC). Link-local addresses start with fe80, and the loopback is ::1." },
  "ISO": { full: "International Organization for Standardization; also an ISO disc image", tip: "The standards body, and the .iso file format that holds a complete disc image.", more: "ISO 9001 is the quality management standard some hospital accreditors use. An ISO file is a disc image you attach to a virtual machine or write to a USB stick to install an operating system." },
  "IT": { full: "Information technology", tip: "Computers, networks, and the people who run them.", more: "IT is the department and the discipline that runs business systems. On the exam it appears in shadow IT (systems staff set up without approval) and in the contrast with operational technology." },
  "IUPC": { full: "Intrauterine pressure catheter", tip: "A catheter that measures contraction pressure directly.", more: "The IUPC gives absolute pressure in mmHg where the external TOCO shows only timing and relative strength." },
  "IV": { full: "Intravenous", tip: "Into a vein; IV lines, pumps, and fluids.", more: "IV infusion pumps deliver fluids and drugs at set rates. Enteral feeding connectors are deliberately incompatible with IV connectors so formula cannot be injected into a vein." },
  "KCL": { full: "Kirchhoff's current law", tip: "Current into a node equals current out.", more: "KCL is used to solve parallel circuits: the branch currents add up to the total. If a computed current comes out negative, it flows opposite the arrow you assumed." },
  "kHz": { full: "Kilohertz", tip: "One thousand cycles per second.", more: "Electrosurgical units operate above about 100 kHz, faster than nerves can respond, which is why they cut without shocking. Ultrasound and some telemetry also use kilohertz ranges." },
  "kV": { full: "Kilovolt", tip: "One thousand volts; X-ray tube voltage and defibrillator charge levels.", more: "In an X-ray tube the kV sets how penetrating the beam is. Defibrillators charge capacitors to a few kilovolts to deliver 120 to 360 joules." },
  "KVL": { full: "Kirchhoff's voltage law", tip: "The voltages around any closed loop sum to zero.", more: "KVL solves series circuits: the drops across each component add up to the source voltage." },
  "KVM": { full: "Keyboard, video, mouse (switch)", tip: "One keyboard, monitor, and mouse shared among several computers.", more: "A KVM switch lets one console control many servers or a technician's bench machines. IP-based KVMs do it over the network for remote server rooms. In the A+ course KVM can also mean the Linux kernel virtual machine hypervisor; read the context." },
  "KVO": { full: "Keep vein open", tip: "A very low infusion rate that keeps an IV line from clotting.", more: "KVO rates of a few mL per hour maintain patency when no active infusion is running." },
  "kW": { full: "Kilowatt", tip: "One thousand watts of power.", more: "Large equipment such as MRI, CT, and sterilizers draws kilowatts. A 60 kWh battery charged at 0.5 C draws 30 kW." },
  "kWh": { full: "Kilowatt-hour", tip: "The energy unit on the electric bill: one kilowatt for one hour.", more: "Energy is power times time. A 60 W lamp for 8 hours uses 480 watt-hours, 0.48 kWh." },
  "LA": { full: "Left arm electrode (also left atrium)", tip: "The black ECG electrode on the left arm; in heart anatomy, the left atrium.", more: "The left arm lead is black in the AHA code. As anatomy, the left atrium receives oxygenated blood from the lungs and feeds the left ventricle." },
  "LAN": { full: "Local area network", tip: "One site's network: a building, floor, or campus that one organization owns and runs.", more: "A LAN is the network inside one location, usually built from switches and Ethernet or Wi-Fi, running at high speed because the organization owns every piece of it. When a question says one office, one building, or one campus, it is describing a LAN. Anything that crosses a provider's link to reach another city is no longer a LAN." },
  "LC50": { full: "Lethal concentration 50 percent", tip: "The airborne concentration lethal to half of test subjects.", more: "LC50 is the inhalation counterpart of LD50." },
  "LCD": { full: "Liquid crystal display", tip: "The flat panel that shapes light from a backlight into an image; TN, IPS, and VA are the panel types.", more: "An LCD needs a backlight, LED today and CCFL in old panels with an inverter. It is sharp only at its native resolution. A dim screen with a faint image points to the backlight or inverter, not the panel." },
  "LD50": { full: "Lethal dose 50 percent", tip: "The dose that kills half of test subjects.", more: "LD50 compares toxicity by ingestion or contact; a lower number is more toxic." },
  "LED": { full: "Light-emitting diode", tip: "A small light source: the status lights on a port, the lamp in cheap fiber transmitters, and modern display backlights.", more: "On network gear the link and activity LEDs are the first thing to check. In fiber, LEDs are the low-cost light source for older multimode links. In displays and medical devices LEDs provide backlights and the red and infrared light in pulse oximeter probes." },
  "LH": { full: "Luteinizing hormone", tip: "The pituitary hormone that drives testosterone and triggers ovulation.", more: "LH pairs with FSH in reproductive physiology." },
  "LIM": { full: "Line isolation monitor", tip: "Continuously measures how much current a fault could drive from an isolated power system to ground and alarms at 5 mA.", more: "Isolated power systems in operating rooms have no ground reference, so a single fault cannot shock. The LIM watches the total hazard current and alarms when it reaches 5 mA, meaning one more fault would be dangerous." },
  "LIMS": { full: "Laboratory information management system", tip: "Sample and workflow tracking software for laboratories.", more: "LIMS overlaps with LIS but is used more in research and reference labs." },
  "LIS": { full: "Laboratory information system", tip: "The software that manages lab orders, analyzer results, and reporting.", more: "Analyzers send results to the LIS, which sends them to the EMR through HL7." },
  "LL": { full: "Left leg electrode", tip: "The red ECG electrode on the left leg.", more: "The left leg lead is red in the AHA code. Lead II runs from right arm to left leg and is the standard monitoring lead." },
  "LV": { full: "Left ventricle", tip: "The chamber that pumps blood to the body at systemic pressure.", more: "The left ventricle has the thickest wall because it drives blood through the whole body. Its contraction produces systolic pressure." },
  "LVP": { full: "Large-volume pump", tip: "An infusion pump for bags of fluid, usually peristaltic, accurate to about 5 percent.", more: "LVPs detect occlusions upstream and downstream, air in line, and door open, and they protect against free flow when the set is removed." },
  "mA": { full: "Milliampere", tip: "One thousandth of an ampere; the unit for shock thresholds and leakage currents.", more: "Perception is about 1 mA, let-go about 10 to 20 mA, and ventricular fibrillation 100 to 300 mA through the body. Chassis leakage limits are in the hundreds of microamps, and microshock through a cardiac catheter needs only 10 microamps." },
  "MAC": { full: "Media access control (address)", tip: "The 48-bit hardware address burned into a network interface, used at Layer 2.", more: "A MAC address is the physical address of a network card, written as six pairs of hex digits. The first half is the manufacturer code (OUI). Switches build a table of which MAC address is on which port and forward frames by it. MAC addresses only matter within one LAN segment; routers use IP addresses to move packets between networks. In Security+ the same letters can also mean mandatory access control." },
  "MAP": { full: "Mean arterial pressure", tip: "The average arterial pressure: diastolic plus one third of the pulse pressure.", more: "MAP = DBP + (SBP - DBP) / 3, because diastole lasts about twice as long as systole. A MAP of at least 60 to 65 mmHg is needed to perfuse organs, and it is the number vasopressor drips are titrated to." },
  "MDDS": { full: "Medical device data system", tip: "Software or hardware that transfers, stores, or displays device data without changing it.", more: "MDDS products are low risk and lightly regulated as long as they do not interpret the data or control the device." },
  "MDS2": { full: "Manufacturer Disclosure Statement for Medical Device Security", tip: "The standard form describing a device's security capabilities.", more: "The MDS2 tells the hospital whether a device can be patched, encrypted, and logged, and what it needs from the network. It is requested before purchase." },
  "MFA": { full: "Multi-factor authentication", tip: "Two or more different kinds of proof of identity.", more: "MFA on remote access and vendor accounts is a basic control for networked medical devices and PHI systems." },
  "MHz": { full: "Megahertz", tip: "Millions of cycles per second; memory speed, radio channels, and older CPU clocks.", more: "Memory is rated in MHz or megatransfers, Wi-Fi channels are 20 to 160 MHz wide, and medical telemetry uses the WMTS bands in the 600 and 1400 MHz ranges." },
  "mL": { full: "Milliliter", tip: "One thousandth of a liter; tidal volumes, drug doses, and infusion rates in mL per hour.", more: "A normal adult breath is about 500 mL; ventilators are set at 6 to 8 mL per kilogram. Infusion pumps deliver in mL per hour and are checked to within about 5 percent." },
  "mmHg": { full: "Millimeters of mercury", tip: "The pressure unit for blood pressure, gas pressures, and vacuum.", more: "One mmHg is the pressure of a millimeter of mercury column; 1 mmHg equals 1.36 cm of water. Blood pressure, partial pressures such as EtCO2, and suction regulators are all read in mmHg." },
  "MR": { full: "Magnetic resonance", tip: "The MRI environment; equipment is labeled MR Safe, MR Conditional, or MR Unsafe.", more: "MR labeling tells staff what may enter the magnet room. Conditional items have specific limits on field strength and position." },
  "MRI": { full: "Magnetic resonance imaging", tip: "Imaging with a strong magnet and radio pulses; no ionizing radiation, but the magnet is always on.", more: "MRI uses a superconducting magnet of 1.5 or 3 tesla. Ferrous objects become projectiles, so zone 4 access is controlled and equipment is labeled MR Safe, MR Conditional, or MR Unsafe. A quench dumps the helium in an emergency. RF interference from outside enters through the shielded room's penetrations." },
  "MRN": { full: "Medical record number", tip: "The hospital's unique identifier for a patient.", more: "Devices and interfaces match patients by MRN or by bed from the ADT feed. Wrong demographics come from a wrong MRN." },
  "ms": { full: "Millisecond", tip: "One thousandth of a second; latency, pulse widths, and ECG timing.", more: "One 60 Hz cycle lasts 16.7 ms. Network latency is quoted in ms, and pacemaker pulses last a fraction of a millisecond." },
  "MSH": { full: "Message header segment", tip: "The first segment of every HL7 version 2 message.", more: "MSH names the sending and receiving applications, message type, timestamp, and the delimiters used." },
  "mV": { full: "Millivolt", tip: "One thousandth of a volt; ECG signals are about 1 mV.", more: "The ECG front end pulls a 1 mV signal out of volts of interference, which is why CMRR and electrode contact matter. Transducer sensitivity is quoted in microvolts per volt per mmHg." },
  "NAT": { full: "Network address translation", tip: "Rewrites private inside addresses to a public address at the router so many hosts can share it.", more: "NAT lets a network use private RFC 1918 addresses internally while presenting one or a few public addresses to the internet. The router keeps a table mapping each inside connection to the outside address and port. Static NAT maps one address to one; dynamic NAT uses a pool; PAT (port address translation) lets a whole network share one public address by varying ports." },
  "NEC": { full: "National Electrical Code", tip: "The US wiring code, NFPA 70.", more: "The NEC governs building wiring, receptacles, grounding, and ampacity. Hospital-grade receptacles and isolated power systems come from it and NFPA 99." },
  "NESC": { full: "National Electrical Safety Code", tip: "The utility-side safety code for power lines and substations.", more: "The NESC covers the utility's side of the meter; the NEC covers the building's." },
  "NFPA": { full: "National Fire Protection Association", tip: "The standards body for fire and electrical safety: NFPA 70 (NEC), NFPA 99 (health care facilities), NFPA 101 (life safety).", more: "NFPA 99 sets hospital electrical safety limits, medical gas rules, and emergency power requirements. NFPA 704 is the diamond hazard placard." },
  "NIAHO": { full: "National Integrated Accreditation for Healthcare Organizations", tip: "DNV's hospital accreditation program.", more: "NIAHO combines Medicare conditions with ISO 9001 and surveys every year instead of every three." },
  "NIBP": { full: "Non-invasive blood pressure", tip: "Automatic cuff measurement by the oscillometric method.", more: "An NIBP monitor inflates the cuff, then senses the oscillations in cuff pressure as it deflates: the largest oscillation marks mean pressure, and systolic and diastolic are derived from the envelope. Cuff size and motion are the usual error sources; a leaking cuff reads low." },
  "NIOSH": { full: "National Institute for Occupational Safety and Health", tip: "The CDC's research arm for workplace safety, which publishes RELs.", more: "NIOSH researches hazards and certifies respirators; OSHA enforces the law." },
  "NIST": { full: "National Institute of Standards and Technology", tip: "The US standards body whose cybersecurity framework hospitals use.", more: "The NIST Cybersecurity Framework (identify, protect, detect, respond, recover) is the common structure for medical device security programs." },
  "NPN": { full: "Negative-positive-negative transistor", tip: "A bipolar transistor that conducts when its base is pulled positive.", more: "A small base current controls a larger collector current. NPN and PNP are the two bipolar types; PNP is the mirror image." },
  "NPSG": { full: "National Patient Safety Goals", tip: "The Joint Commission's annual list of safety priorities, including alarm management.", more: "NPSGs drive policies such as clinical alarm safety and patient identification." },
  "NTC": { full: "Negative temperature coefficient (thermistor)", tip: "A thermistor whose resistance falls as temperature rises; the sensor in patient temperature probes.", more: "NTC probes follow curve standards such as YSI 400 and YSI 700, which are not interchangeable; the monitor must match the probe." },
  "NTP": { full: "National Toxicology Program, or Network Time Protocol", tip: "The US program that lists carcinogens; in the networking lessons, the protocol that keeps device clocks synchronized.", more: "In the hazards lessons, NTP is the National Toxicology Program, which publishes the Report on Carcinogens alongside IARC and OSHA listings. In the healthcare IT lessons, NTP is the Network Time Protocol (UDP 123) that synchronizes clocks across monitors, servers, and network gear so logs and alarms line up. Read the sentence to tell which is meant." },
  "OBR": { full: "Observation request segment", tip: "The HL7 segment describing the order a result answers.", more: "OBR identifies which test or observation the following OBX segments belong to." },
  "OBX": { full: "Observation segment", tip: "The HL7 segment holding one observation and its value.", more: "Each vital sign or lab value is an OBX segment with an identifier, value, and units." },
  "OCR": { full: "Office for Civil Rights", tip: "The HHS office that enforces HIPAA privacy and security rules.", more: "OCR investigates complaints and breaches and issues penalties." },
  "OR": { full: "Operating room", tip: "The surgical suite, with isolated power, ESUs, anesthesia machines, and lasers.", more: "OR receptacles may be duplex or quadruplex on isolated power with a line isolation monitor. In other courses OR is just the English word in emphasis." },
  "ORM": { full: "Order message", tip: "The HL7 version 2 message that carries an order.", more: "ORM messages send orders from the EMR to labs, radiology, and pharmacy." },
  "ORU": { full: "Observation result", tip: "The HL7 message that carries results, including vital signs from monitors.", more: "A monitor sending vitals to the EMR does so as ORU messages containing OBX segments." },
  "OSHA": { full: "Occupational Safety and Health Administration", tip: "The US agency that sets workplace safety rules.", more: "OSHA rules cover hazard communication, electrical safety, bloodborne pathogens, and lifting. Its Hazard Communication Standard is why safety data sheets exist." },
  "OSI": { full: "Open Systems Interconnection model", tip: "The seven-layer model for describing where a network function happens.", more: "Hubs work at Layer 1, switches at Layer 2 with MAC addresses, routers at Layer 3 with IP addresses, TCP and UDP at Layer 4, and HL7 and DICOM at the application layer." },
  "OX": { full: "Oxidizer (NFPA 704 symbol)", tip: "The special hazard code in the white diamond for oxidizing materials.", more: "The NFPA 704 diamond shows health, flammability, and instability from 0 to 4, plus a white box for special hazards such as OX for oxidizer and W with a line through it for water reactive." },
  "PaaS": { full: "Platform as a service", tip: "The provider runs the platform (OS, runtime, database); you deploy code.", more: "PaaS gives developers a managed environment to run applications without administering servers. You bring the code and data; the provider handles patching, scaling, and the runtime." },
  "PACS": { full: "Picture archiving and communication system", tip: "The server that stores and distributes medical images using DICOM.", more: "Imaging modalities send studies to PACS, and workstations retrieve them. Patient demographics come from the RIS or EMR through HL7." },
  "PASS": { full: "Pull, aim, squeeze, sweep", tip: "How to use a fire extinguisher.", more: "Pull the pin, aim at the base of the fire, squeeze the handle, sweep side to side. Use a class C or ABC extinguisher on energized electrical equipment; never water." },
  "PC": { full: "Personal computer", tip: "A desktop or laptop for one user.", more: "The PC is the machine the A+ exam takes apart: motherboard, CPU, RAM, storage, power supply, and ports. In networking questions it is the client behind the phone or on the switch port." },
  "PCA": { full: "Patient-controlled analgesia", tip: "An infusion pump that lets the patient self-dose pain medication within programmed limits.", more: "PCA pumps enforce a lockout interval and dose limits. Programming errors, such as a wrong concentration, are the classic PCA incident; drug libraries and independent double checks prevent them." },
  "PCB": { full: "Printed circuit board", tip: "The board that holds and connects a device's components.", more: "A faulty input PCB is the answer when one parameter fails while others work. Boards are replaced as units in most field service." },
  "PDCA": { full: "Plan, do, check, act", tip: "The continuous improvement cycle.", more: "PDCA structures quality projects: plan a change, try it, measure, then standardize or adjust." },
  "PEEP": { full: "Positive end-expiratory pressure", tip: "Pressure the ventilator keeps in the lungs at the end of exhalation so alveoli stay open.", more: "PEEP improves oxygenation by preventing alveolar collapse, typically 5 cmH2O or more. Too much reduces venous return and blood pressure." },
  "PEL": { full: "Permissible exposure limit", tip: "OSHA's legal maximum exposure to a substance, averaged over a shift.", more: "PELs are enforceable; TLVs from ACGIH and RELs from NIOSH are recommendations, usually stricter." },
  "PET": { full: "Positron emission tomography", tip: "Nuclear imaging of metabolic activity using a positron-emitting tracer such as FDG.", more: "PET detects pairs of gamma photons produced when positrons meet electrons. It is usually combined with CT for anatomy and used mainly in oncology." },
  "pH": { full: "Potential of hydrogen", tip: "The acidity scale; blood is normally 7.35 to 7.45.", more: "Blowing off CO2 raises blood pH; retaining it lowers pH. Blood gas analyzers measure pH with a glass electrode." },
  "PHI": { full: "Protected health information", tip: "Any health information tied to an identifiable person.", more: "PHI on devices must be encrypted, access limited, and sanitized before the device leaves the facility. Vendors handling it sign a BAA." },
  "PID": { full: "Patient identification segment", tip: "The HL7 segment carrying patient name, ID, and demographics.", more: "PID is how a system matches a message to a patient, by medical record number. In the A+ course PID is a process identifier; read the context." },
  "PM": { full: "Preventive maintenance", tip: "Scheduled inspection and testing of equipment before it fails.", more: "PM intervals come from manufacturer recommendations or an alternative equipment maintenance program. A PM includes safety tests, performance checks, battery runtime tests, and documentation in the CMMS." },
  "PNP": { full: "Positive-negative-positive transistor", tip: "A bipolar transistor that conducts when its base is pulled negative.", more: "PNP transistors are the complement of NPN. Together they form push-pull output stages." },
  "PoE": { full: "Power over Ethernet", tip: "Delivers DC power to devices over the data cable: 802.3af 15.4 W, 802.3at 30 W, 802.3bt 60 to 90 W.", more: "PoE lets phones, access points, and cameras run from the switch port with no separate power supply. A PoE switch (endspan) or an injector (midspan) supplies it. The device negotiates how much it may draw. If a device reboots or will not power up, check the switch's PoE budget and the standard it supports." },
  "PP": { full: "Pulse pressure", tip: "Systolic minus diastolic pressure.", more: "Pulse pressure is the swing between the two readings; MAP equals diastolic plus one third of it." },
  "PPE": { full: "Personal protective equipment", tip: "Gloves, gowns, masks, eye protection, and lead aprons.", more: "PPE is the last line of defense after engineering and administrative controls. Standard precautions require it for any contact with blood or body fluids; lead aprons protect against scatter radiation." },
  "PPP": { full: "Point-to-Point Protocol", tip: "The Layer 2 protocol for serial and dial-up links that carries IP with authentication.", more: "PPP frames IP over point-to-point links such as router serial interfaces and DSL (as PPPoE), with authentication by PAP or CHAP." },
  "PR": { full: "PR interval", tip: "The ECG interval from the start of the P wave to the start of the QRS, 0.12 to 0.20 seconds; the AV node delay.", more: "A long PR interval means the AV node is slow (first-degree block). Paper math: at 25 mm/s each small box is 0.04 seconds." },
  "psi": { full: "Pounds per square inch", tip: "The pressure unit for cylinders, sterilizers, and pneumatic systems.", more: "Steam sterilizers run at about 121 C and 15 psi. Medical gas pipelines run at 50 psi and cylinders at up to 2200 psi." },
  "PSU": { full: "Power supply unit", tip: "Converts wall AC to the DC voltages a computer needs: 12 V, 5 V, 3.3 V.", more: "The PSU is rated in watts and must cover the CPU, graphics card, and drives with margin. Connectors include the 24-pin main, EPS 4 or 8-pin CPU, PCIe 6 and 8-pin, SATA, and the newer 12VHPWR. Modular supplies let you attach only the cables you need. A PSU that dies of heat, or a paperclip test that will not start it, are classic scenarios." },
  "PSV": { full: "Pressure support ventilation", tip: "The ventilator boosts each spontaneous breath with a set pressure.", more: "Pressure support helps a breathing patient overcome the resistance of the tube and circuit and is used for weaning." },
  "PT": { full: "Physical therapy", tip: "The rehabilitation department, whose equipment includes TENS units, stimulators, and therapeutic ultrasound.", more: "PT devices are checked for output accuracy and electrical safety like any patient-connected equipment." },
  "QC": { full: "Quality control", tip: "Running known samples to verify an analyzer is reading correctly.", more: "Lab analyzers run QC material each shift; results outside limits stop patient testing until fixed." },
  "QRS": { full: "QRS complex", tip: "The sharp ECG spike of ventricular depolarization; normally under 0.12 seconds wide.", more: "The QRS is the largest feature on the ECG and what monitors and defibrillators detect for heart rate and synchronization. A wide QRS suggests a ventricular origin or a conduction block." },
  "QT": { full: "QT interval", tip: "The ECG interval from the start of the QRS to the end of the T wave, under about 0.44 seconds.", more: "A prolonged QT interval raises the risk of dangerous arrhythmias and is watched when giving certain drugs." },
  "RA": { full: "Right arm electrode (also right atrium)", tip: "The white ECG electrode on the right arm; in heart anatomy, the right atrium.", more: "In the AHA color code the right arm lead is white. In blood-flow shorthand RA is the right atrium, which receives venous blood before the right ventricle. In Security+ RA is a registration authority and in Network+ a router advertisement; read the context." },
  "RACE": { full: "Rescue, alarm, confine, extinguish or evacuate", tip: "The order of actions when a fire is discovered.", more: "Rescue anyone in immediate danger, activate the alarm, confine the fire by closing doors, then extinguish if small or evacuate." },
  "RADIUS": { full: "Remote Authentication Dial-In User Service", tip: "The AAA server behind Wi-Fi Enterprise, VPNs, and 802.1X; UDP 1812 and 1813.", more: "A RADIUS server checks credentials for network access devices (switches, APs, VPN gateways) and tells them what the user is allowed. It encrypts only the password, uses UDP, and combines authentication and authorization, which is why TACACS+ is preferred for device administration." },
  "RAID": { full: "Redundant array of independent disks", tip: "Combining disks for speed, capacity, or fault tolerance: 0 stripe, 1 mirror, 5 stripe with parity, 6 double parity, 10 mirrored stripes.", more: "RAID 0 stripes data across disks for speed with no redundancy; one failure loses everything. RAID 1 mirrors two disks. RAID 5 stripes with one parity block and survives one disk failure (three disks minimum). RAID 6 has two parity blocks and survives two failures (four disks). RAID 10 mirrors pairs then stripes, needing four disks. RAID is availability, not backup." },
  "RAM": { full: "Random-access memory", tip: "The working memory that holds running programs and data; lost at power off.", more: "RAM speed and capacity limit how much a system can do at once. Because it is volatile, forensics collects it first (order of volatility) before the machine is powered down." },
  "RC": { full: "Resistor-capacitor (circuit)", tip: "A resistor and capacitor together, whose time constant is R times C.", more: "A capacitor charging through a resistor reaches 63 percent of full voltage in one time constant and is essentially full after five. RC filters set the frequency response of monitor front ends." },
  "RCA": { full: "Root cause analysis", tip: "A structured investigation of what happened, why, and how to prevent it.", more: "RCA follows sentinel events: it asks what, why, and how, looks at systems rather than blame, and produces an action plan." },
  "RCF": { full: "Relative centrifugal force", tip: "The g-force a centrifuge applies, which depends on speed and rotor radius.", more: "Protocols specify RCF in g, not RPM, because the same RPM gives different force on different rotors." },
  "REL": { full: "Recommended exposure limit", tip: "NIOSH's recommended exposure limit.", more: "RELs are research-based recommendations that are usually stricter than the legal PEL." },
  "REM": { full: "Roentgen equivalent man", tip: "A unit of radiation dose equivalent, 100 rem equals 1 sievert.", more: "Occupational dose limits are set in rem or millisieverts. Badges record cumulative dose. On an ESU analyzer, REM refers to the return electrode monitor check." },
  "RF": { full: "Radio frequency", tip: "Radio signals; the medium of Wi-Fi, cellular, and Bluetooth, and a source of interference and, in medicine, surgical energy.", more: "RF covers everything from Wi-Fi channels and site surveys to RF leakage on an electrosurgical unit. Interference, absorption by walls, and antenna choice all shape RF coverage." },
  "RIS": { full: "Radiology information system", tip: "Scheduling, tracking, and reporting for imaging departments.", more: "The RIS manages orders and reports while PACS stores the images; both talk to the EMR." },
  "RJ45": { full: "Registered jack 45", tip: "The eight-pin plug on Ethernet twisted-pair cables (properly an 8P8C connector).", more: "RJ45 is the everyday name for the Ethernet plug. It has eight positions and eight contacts, crimped onto four twisted pairs following the T568A or T568B pin-out. The smaller RJ11 is the telephone version." },
  "RL": { full: "Right leg electrode", tip: "The green ECG electrode on the right leg, the reference or driven ground.", more: "The right leg lead is not used for a trace; it is the reference that the driven-right-leg circuit uses to cancel common-mode interference." },
  "RMS": { full: "Root mean square", tip: "The effective value of an AC voltage or current, the DC equivalent for heating; 120 V mains is RMS.", more: "RMS equals peak divided by 1.414 for a sine wave. Multimeters read RMS; oscilloscopes show peak values. True-RMS meters are needed for non-sine waveforms such as ESU output." },
  "RPM": { full: "Revolutions per minute", tip: "Rotation speed: hard drive platters at 5400 or 7200, fans, and laboratory centrifuges.", more: "Faster platters mean quicker access. In the CBET course centrifuge speed is set in RPM, but the force that separates samples is the relative centrifugal force, which also depends on the rotor radius." },
  "RS-232": { full: "Recommended Standard 232 serial", tip: "The classic serial port: slow, simple, and still used for console access and legacy devices.", more: "RS-232 uses a DB9 connector on PCs and RJ45 or USB console cables on network gear. Older medical devices and lab analyzers still use it for data output." },
  "RTLS": { full: "Real-time location system", tip: "Tags and receivers that track equipment location inside the hospital.", more: "RTLS uses Wi-Fi, RFID, infrared, or ultrasound tags so staff can find pumps and biomeds can find devices due for PM." },
  "RV": { full: "Right ventricle", tip: "The chamber that pumps blood to the lungs.", more: "Blood flows body, right atrium, right ventricle, lungs, left atrium, left ventricle, body. The right ventricle works at low pressure." },
  "SA": { full: "Sinoatrial node", tip: "The heart's natural pacemaker in the right atrium.", more: "The SA node fires first, producing the P wave. Its rate sets the heart rate under nervous and hormonal control." },
  "SaaS": { full: "Software as a service", tip: "Complete applications delivered over the web, such as email and office suites.", more: "With SaaS you log in and use the software; the provider runs everything. It is the model with the least customer responsibility and the least control." },
  "SAT": { full: "Source address table", tip: "The switch's table of which MAC address lives on which port.", more: "A switch learns source addresses from incoming frames and forwards later frames only to the right port, unlike a hub that repeats everything." },
  "SBOM": { full: "Software bill of materials", tip: "A list of the software components inside a device.", more: "An SBOM lets the hospital know when a vulnerability in a library affects a device, which is why the FDA now expects one." },
  "SBP": { full: "Systolic blood pressure", tip: "The peak arterial pressure during ventricular contraction.", more: "Systolic pressure is the first Korotkoff sound when a cuff is deflated and the top number of a reading." },
  "SCD": { full: "Sequential compression device", tip: "Inflatable leg sleeves that inflate in sequence to prevent blood clots.", more: "SCDs inflate chambers from ankle to thigh at about 35 to 55 mmHg to push venous blood upward. Faults are usually leaks, tubing, or the pump." },
  "SCR": { full: "Silicon-controlled rectifier", tip: "A thyristor that switches large currents on when triggered and stays on until current stops.", more: "SCRs and triacs control heaters, motors, and lamp dimmers by switching AC loads. Once fired, an SCR conducts until the current falls to zero." },
  "SDS": { full: "Safety data sheet", tip: "The document describing a chemical's hazards, handling, and first aid.", more: "Staff must be able to reach the SDS for anything they use, from cleaning agents to laboratory reagents. It has sixteen sections in the GHS format." },
  "SIMV": { full: "Synchronized intermittent mandatory ventilation", tip: "A ventilator mode that gives a set number of breaths synchronized with the patient's own efforts.", more: "SIMV delivers mandatory breaths at a set rate but lets the patient breathe spontaneously in between, often with pressure support." },
  "SMART": { full: "Self-Monitoring, Analysis, and Reporting Technology", tip: "Hard drive self-diagnostics that warn before failure.", more: "SMART warnings on a workstation drive mean back up, replace the drive, and restore the image." },
  "SMB": { full: "Server Message Block", tip: "Windows file and printer sharing on TCP 445.", more: "SMB is the protocol behind mapped drives and shared printers. Version 1 is insecure and should be disabled; versions 2 and 3 add signing and encryption. Blocking 445 at the perimeter stops most worm-style spread." },
  "SMDA": { full: "Safe Medical Devices Act", tip: "The 1990 law requiring hospitals to report device-related deaths and serious injuries to the FDA and manufacturer.", more: "Under SMDA a death must be reported within 10 working days to the FDA and manufacturer; a serious injury to the manufacturer (or FDA if unknown)." },
  "SMPS": { full: "Switch-mode power supply", tip: "A power supply that switches at high frequency to regulate voltage efficiently.", more: "SMPS designs are small and efficient but generate ripple and noise that must be filtered. Most medical device power supplies are switch-mode." },
  "SpO2": { full: "Peripheral oxygen saturation", tip: "The percentage of hemoglobin carrying oxygen, measured by a pulse oximeter.", more: "A pulse oximeter shines red (about 660 nm) and infrared (about 940 nm) light through a fingertip and compares absorption to compute saturation, normally 95 to 100 percent. Carbon monoxide poisoning reads falsely high; poor perfusion, motion, and nail polish cause errors." },
  "SSD": { full: "Solid-state drive", tip: "Flash storage with no moving parts: fast, silent, and shock resistant.", more: "SATA SSDs reach about 550 MB/s; NVMe SSDs several thousand MB/s. TRIM keeps them fast by telling the drive which blocks are free. They wear with writes but far outlast most systems." },
  "SSH": { full: "Secure Shell", tip: "Encrypted remote command-line access and file transfer on TCP 22; replaces Telnet and FTP.", more: "SSH authenticates with passwords or keys and encrypts the whole session. SFTP and SCP ride on it for file copies. Any question about managing a switch or server securely from the command line wants SSH." },
  "ST": { full: "ST segment", tip: "The ECG segment between the QRS and the T wave, where injury and ischemia show as elevation or depression.", more: "Monitors measure ST deviation to detect heart attacks. In networking courses ST is a fiber connector; read the context." },
  "STEL": { full: "Short-term exposure limit", tip: "The maximum average exposure over a 15-minute period.", more: "A STEL protects against brief high exposures that an 8-hour average would hide." },
  "SVT": { full: "Supraventricular tachycardia", tip: "A fast, regular rhythm originating above the ventricles, with narrow QRS.", more: "SVT is rapid and regular with normal-width QRS complexes, which distinguishes it from ventricular tachycardia." },
  "TC": { full: "Transport Canada", tip: "The Canadian counterpart of the DOT for cylinder rules.", more: "Cylinders in Canada carry TC markings equivalent to US DOT markings." },
  "TCP": { full: "Transmission Control Protocol", tip: "Reliable, ordered, connection-based transport: three-way handshake, acknowledgments, retransmission.", more: "TCP sets up a connection with a SYN, SYN-ACK, ACK handshake, numbers every segment, acknowledges what arrives, and resends what does not. That reliability costs overhead, so it suits web pages, email, and file transfer rather than live voice. Port numbers at Layer 4 identify which application on the host the data is for." },
  "TDR": { full: "Time-domain reflectometer", tip: "A cable tester that finds the distance to a break from signal reflections.", more: "A TDR sends a pulse down a cable and times the echo, reporting how far away the fault is." },
  "TENS": { full: "Transcutaneous electrical nerve stimulation", tip: "Low-level electrical pulses through skin electrodes for pain relief.", more: "TENS units are physical therapy devices. Their output is checked with a load and an oscilloscope." },
  "TLS": { full: "Transport Layer Security", tip: "The encryption layer under HTTPS and most secure protocols; use 1.2 or 1.3.", more: "TLS authenticates the server with a certificate, agrees session keys, and then encrypts the connection. It replaced SSL, whose versions are all deprecated. TLS 1.0 and 1.1 are also retired. It works at the presentation and session layers in OSI terms and protects web, mail, LDAP, and VPN traffic." },
  "TLV": { full: "Threshold limit value", tip: "The ACGIH recommended exposure limit.", more: "TLVs are expert recommendations updated more often than OSHA's PELs." },
  "TOCO": { full: "Tocodynamometer", tip: "The pressure sensor on a fetal monitor that records uterine contractions.", more: "The TOCO belt senses abdominal firmness as a relative pressure. An intrauterine pressure catheter gives absolute readings." },
  "TPN": { full: "Total parenteral nutrition", tip: "Complete nutrition delivered into a vein through an infusion pump.", more: "Parenteral means bypassing the gut. TPN goes through a central line via an ordinary infusion pump; enteral feeding uses a separate pump and incompatible connectors." },
  "TR": { full: "Telecommunications room", tip: "The wiring closet on each floor that serves nearby devices within the 90 m horizontal cable limit.", more: "Standards call for at least one TR per floor, each serving no more than about 20,000 square feet, with horizontal runs under 90 m plus patch cords." },
  "TV": { full: "Television", tip: "A display or broadcast receiver; smart TVs are IoT devices.", more: "Cable TV shares the coax with the cable modem. Smart TVs join the network and should be segmented like other IoT." },
  "UDP": { full: "User Datagram Protocol", tip: "Connectionless, fast transport with no delivery guarantee; used for voice, video, DNS, DHCP.", more: "UDP sends datagrams without a handshake, without acknowledgments, and without retransmission. That makes it fast and light, which is what real-time voice and video want, since a late packet is useless anyway. DNS queries, DHCP, TFTP, SNMP, and syslog also ride on UDP." },
  "UEFI": { full: "Unified Extensible Firmware Interface", tip: "Modern firmware that replaces BIOS: GPT disks, Secure Boot, mouse-driven setup.", more: "UEFI boots from GPT disks of any size, verifies boot loaders with Secure Boot, and offers a graphical setup. A compatibility mode (CSM) boots legacy BIOS-style systems. Windows 11 requires UEFI with Secure Boot and a TPM." },
  "UN": { full: "United Nations", tip: "The body whose Globally Harmonized System is the format hazard communication now uses.", more: "The GHS pictograms and sixteen-section safety data sheet come from the UN; OSHA's HazCom rule adopted them." },
  "UPS": { full: "Uninterruptible power supply", tip: "A battery unit that keeps equipment running through a power cut and conditions the power.", more: "A UPS sits between the wall and the equipment, taking over instantly when power fails and giving time to shut down or for a generator to start. It is sized in VA or watts against the load for the runtime needed. In medical settings a UPS covers the transfer gap to emergency power." },
  "US": { full: "United States", tip: "The country; used for US standards, the 60 Hz mains frequency, and the AHA electrode color code.", more: "The US uses 120 V at 60 Hz and the AHA (white, black, green, red, brown) ECG color code, while much of the world uses 50 Hz and the IEC colors." },
  "USB": { full: "Universal Serial Bus", tip: "The standard port for peripherals, storage, and charging.", more: "USB versions set speed: 2.0 at 480 Mbps, 3.0 at 5 Gbps, 3.1 at 10 Gbps, 3.2 at 20 Gbps, USB4 at 40 Gbps. Connectors include A, B, mini, micro, and the reversible C. Unknown USB drives are a malware vector, which DLP and device control address." },
  "uV": { full: "Microvolt", tip: "One millionth of a volt; EEG signals are in microvolts.", more: "EEG amplitudes of tens of microvolts require very low-noise amplifiers and careful shielding. Pressure transducers are rated at 5 uV per volt per mmHg." },
  "UV": { full: "Ultraviolet", tip: "Light beyond violet, used for disinfection and in spectrophotometers, and absorbed by glass and plastic.", more: "UV germicidal lamps disinfect air and surfaces; spectrophotometers use UV wavelengths, which is why quartz cuvettes are required. A dim or dead UV lamp is the first suspect in either." },
  "VA": { full: "Volt-ampere", tip: "The unit of apparent power, which a supply must deliver regardless of power factor.", more: "Apparent power S in VA is the vector sum of real power P in watts and reactive power Q in VAR. UPS units and transformers are rated in VA." },
  "VAR": { full: "Volt-ampere reactive", tip: "The unit of reactive power, which shuttles between source and load without doing work.", more: "Reactive power Q in VAR comes from inductive and capacitive loads. Apparent power S in VA is the vector sum of real power P in watts and Q." },
  "VF": { full: "Ventricular fibrillation", tip: "Chaotic ventricular activity with no output; the rhythm defibrillators treat.", more: "VF produces no pulse and looks like a chaotic squiggle. Immediate defibrillation and CPR are the treatment; AEDs advise a shock only for VF and pulseless VT." },
  "VLAN": { full: "Virtual local area network", tip: "A logical LAN on a switch: ports in different VLANs are separate broadcast domains.", more: "A VLAN splits one physical switch into several logical switches. Ports in VLAN 10 cannot talk to ports in VLAN 20 without a router or Layer 3 switch, which contains broadcasts and separates traffic such as voice, data, and guests. Trunk links carry many VLANs between switches using 802.1Q tags. A native VLAN is the untagged one on a trunk, and a voice VLAN lets a phone tag its traffic while the PC behind it stays untagged." },
  "VM": { full: "Virtual machine", tip: "A complete computer running as software on a hypervisor.", more: "A VM has its own operating system and virtual hardware but shares the physical host with others. Type 1 hypervisors run on bare metal; type 2 run on a host OS. VM escape, where code in a guest reaches the host, is the serious virtualization vulnerability; VM sprawl is the management one." },
  "VPN": { full: "Virtual private network", tip: "An encrypted tunnel across an untrusted network such as the internet.", more: "A VPN makes a remote user or site appear to be on the private network by encrypting traffic between the endpoints. Site-to-site VPNs join offices, usually with IPsec; remote-access VPNs connect individual users with IPsec or TLS clients. Split tunneling sends only corporate traffic through the tunnel; full tunneling sends everything." },
  "VT": { full: "Ventricular tachycardia", tip: "A fast rhythm from the ventricles with wide QRS complexes; pulseless VT is shockable.", more: "VT is rapid and wide. With a pulse it may be treated with drugs or synchronized cardioversion; without a pulse it is defibrillated. In the A+ course VT is Intel's virtualization technology; read the context." },
  "WAN": { full: "Wide area network", tip: "Connects LANs across cities or countries, usually over links leased from a provider.", more: "A WAN joins sites that are far apart. Because the organization cannot run its own cable between cities, it rents circuits or internet connections from a carrier, which is why WAN links are slower and cost per month. The internet is the largest WAN. Routers sit at the edge of each site to send traffic across the WAN." },
  "WEP": { full: "Wired Equivalent Privacy", tip: "The original Wi-Fi encryption, broken in minutes; never use it.", more: "WEP used the RC4 cipher with short, badly managed keys, and tools can recover the key from captured traffic in minutes. Any question describing WEP wants you to replace it with WPA2 or WPA3." },
  "Wi-Fi": { full: "Wireless fidelity", tip: "The trade name for IEEE 802.11 wireless networking.", more: "Wi-Fi is the brand the Wi-Fi Alliance gives to interoperable 802.11 equipment. Generations are numbered: Wi-Fi 4 is 802.11n, Wi-Fi 5 is 802.11ac, Wi-Fi 6 and 6E are 802.11ax (6E adds the 6 GHz band), and Wi-Fi 7 is 802.11be. Bands are 2.4 GHz (range, interference), 5 GHz (speed, more channels), and 6 GHz." },
  "WIPO": { full: "World Intellectual Property Organization", tip: "The UN agency for international copyright and patent treaties.", more: "The DMCA implemented WIPO treaties in US law." },
  "WLAN": { full: "Wireless local area network", tip: "A LAN delivered over Wi-Fi instead of cables.", more: "A WLAN is the same idea as a LAN, but the clients connect by radio to access points instead of by cable to a switch. The access points still plug into the wired LAN, so a WLAN is an extension of the LAN rather than a separate network. Wi-Fi is the family of standards (IEEE 802.11) that most WLANs use." },
  "WMTS": { full: "Wireless Medical Telemetry Service", tip: "The FCC-protected bands for patient telemetry: 608 to 614, 1395 to 1400, and 1427 to 1432 MHz.", more: "WMTS bands are reserved so telemetry does not compete with consumer devices. Systems must be registered with the frequency coordinator." },
  "WPA2": { full: "Wi-Fi Protected Access 2", tip: "Wi-Fi security using AES with CCMP; still common and acceptable.", more: "WPA2 replaced TKIP with AES-CCMP encryption. Personal mode uses a pre-shared passphrase; Enterprise mode authenticates each user through 802.1X and RADIUS. Its weakness is that a captured handshake can be attacked offline with password guessing, which WPA3 fixes." },
  "WPA3": { full: "Wi-Fi Protected Access 3", tip: "The current Wi-Fi security standard: SAE in Personal mode, stronger encryption, protected management frames.", more: "WPA3 Personal replaces the pre-shared key handshake with SAE (simultaneous authentication of equals), which stops offline password cracking and adds forward secrecy. Enterprise mode still uses 802.1X. Protected management frames are mandatory, blocking deauthentication attacks." },
  "XML": { full: "Extensible Markup Language", tip: "A text format for structured data; HL7 version 3 and CDA use it.", more: "XML wraps data in nested tags. It is verbose but readable by both people and programs." },
  "YAG": { full: "Yttrium aluminum garnet (laser)", tip: "The crystal in Nd:YAG lasers, which emit near-infrared light that penetrates tissue.", more: "Nd:YAG lasers coagulate deep tissue; CO2 lasers work on the surface. Eye protection must match the wavelength." },
  "YSI": { full: "Yellow Springs Instruments (temperature probe standard)", tip: "The company whose YSI 400 and YSI 700 thermistor curves became the standards for temperature probes.", more: "A YSI 400 probe on a monitor expecting YSI 700 reads wrong. Check the probe type when temperature readings are off." }
};
// Uppercase words in the course text that are not acronyms (emphasis, registry key names, model numbers, formula symbols).
FRA.acronymIgnore = ["BEST","CV","FALSE","FIRST","II","III","IR","LEAST","MOST","NOT","OK","VI","WIDE","XC","XL"];
